def read_and_publish_adc_values():
    try:
        for channel in channel_map:
            adc_value = read_adc(channel)
            if adc_value is None:
                print(f"Error reading ADC channel {channel_map[channel]}")
                continue
            mqtt_client.publish(f"ads1115/channel{channel}", str(adc_value))

        time.sleep(0.05)

    except KeyboardInterrupt:
        i2c.deallocate()
        mqtt_client.disconnect()
        sys.exit(0)

def read_adc(channel):
    try:
        ads.gain = Adafruit_ADS1x15.GAIN_ONE
        ads.data_rate = Adafruit_ADS1x15.RATE_128SPS
        ads.mode = Adafruit_ADS1x15.MODE_SINGLE_SHOT
        ads.channel = channel
        ads.convert()

        start_time = time.monotonic()
        while ads.busy:
            if time.monotonic() - start_time > 0.1:
                return None
            time.sleep(0.01)

        return ads.read()

    except Exception as e:
        print(f"Error reading ADC channel {channel_map[channel]}: {e}")
        return None

