import time
import logging
import gpiozero
import spidev
import adafruit_mcp3008
import picamera2
import paho.mqtt.client as mqtt

class SmartGardenController:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

        self.i2c_bus = spidev.SpiDev()
        self.i2c_bus.open(0, 0)
        self.i2c_bus.max_speed_hz = 1350000
        self.mcp3008 = adafruit_mcp3008.MCP3008(self.i2c_bus)

        self.pump = gpiozero.OutputDevice(18, active_high=True)

        self.dry_threshold = 450

    def read_moisture(self):
        try:
            return self.mcp3008.read_channel(0)
        except Exception as e:
            self.logger.error(f"Error reading moisture: {e}")
            return -1

    def run_pump(self, seconds):
        self.pump.on()
        time.sleep(seconds)
        self.pump.off()

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture > self.dry_threshold:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self.i2c_bus.close()
        self.pump.off()

def schedule_cycles(controller, cycle_count, interval_seconds):
    while cycle_count > 0:
        if controller.irrigation_cycle():
            cycle_count -= 1
        time.sleep(interval_seconds)

if __name__ == "__main__":
    logging.basicConfig(format="%(asctime)s - %(message)s", filename="smart_garden.log", level=logging.INFO)

    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        controller.close()
    finally:
        controller.close()

import time
import os
import gpiozero
import RPi.GPIO as GPIO
import spidev
import dht
import adafruit_mcp3008
import paho.mqtt.client as mqtt
from datetime import datetime

# Set up GPIO pins
GPIO.setmode(GPIO.BCM)

# Define pins for actuators and status LED
Pump_Pin = 17
Fan_Pin = 27
Light_Pin = 22
Status_LED_Pin = 25

# Set up GPIO pins for output
GPIO.setup(Pump_Pin, GPIO.OUT)
GPIO.setup(Fan_Pin, GPIO.OUT)
GPIO.setup(Light_Pin, GPIO.OUT)
GPIO.setup(Status_LED_Pin, GPIO.OUT)

# DHT22 sensor on BCM4 with 5.1kΩ pull-up to 3.3V
DHT22_PIN = 4
dht22 = dht.DHT22(DHT22_PIN)

# MCP3008 ADC on SPI (CS/CE0 on BCM8, MOSI on BCM10, MISO on BCM9, SCLK on BCM11)
ADC = adafruit_mcp3008.MCP3008(spi=spidev.SpiDev())

# MQTT broker and topic
MQTT_BROKER = "your_mqtt_broker"
MQTT_TOPIC = "greenhouse"

# Watchdog timer (600 seconds)
WATCHDOG_TIMEOUT = 600
watchdog_timer = WATCHDOG_TIMEOUT

def control_pump(command):
    if command == "on":
        GPIO.output(Pump_Pin, GPIO.HIGH)
    elif command == "off":
        GPIO.output(Pump_Pin, GPIO.LOW)
    else:
        raise ValueError("Invalid command for pump control")

def control_fan(command):
    if command == "on":
        GPIO.output(Fan_Pin, GPIO.HIGH)
    elif command == "off":
        GPIO.output(Fan_Pin, GPIO.LOW)
    else:
        raise ValueError("Invalid command for fan control")

def control_light(command):
    if command == "on":
        GPIO.output(Light_Pin, GPIO.HIGH)
    elif command == "off":
        GPIO.output(Light_Pin, GPIO.LOW)
    else:
        raise ValueError("Invalid command for light control")

def set_led_status(mode):
    if mode == "online":
        GPIO.output(Status_LED_Pin, GPIO.HIGH)
    elif mode == "offline":
        GPIO.output(Status_LED_Pin, GPIO.LOW)
    elif mode == "error":
        for _ in range(5):
            GPIO.output(Status_LED_Pin, GPIO.HIGH)
            time.sleep(0.2)
            GPIO.output(Status_LED_Pin, GPIO.LOW)
            time.sleep(0.2)
    elif mode == "synchronizing":
        for _ in range(5):
            GPIO.output(Status_LED_Pin, GPIO.HIGH)
            time.sleep(0.2)
            GPIO.output(Status_LED_Pin, GPIO.LOW)
            time.sleep(0.2)
    else:
        raise ValueError("Invalid LED status mode")

def log(message):
    with open("greenhouse.log", "a") as log_file:
        log_file.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")

def read_dht22():
    try:
        dht22.measure()
        temp = dht22.temperature
        humidity = dht22.humidity
        return temp, humidity
    except RuntimeError as e:
        log(f"DHT22 error: {e}")
        return None, None

def read_adc(channel):
    try:
        data = ADC.read_raw(channel)
        return data / 1024 * 5.0
    except OSError as e:
        log(f"ADC error: {e}")
        return None

def check_and_log_errors():
    if not GPIO.all_ok():
        log("GPIO setup error")
    if not ADC.bus.is_open:
        log("ADC bus not open")

def watchdog():
    global watchdog_timer
    while True:
        if watchdog_timer > 0:
            watchdog_timer -= 300
        else:
            log("No sensor data read or actuator command processed for 600 seconds, restarting...")
            os.execv(os.path.realpath(__file__), [sys.executable, __file__])
        time.sleep(300)

def main():
    check_and_log_errors()

    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = lambda client, userdata, flags, rc: log(f"Connected to MQTT broker with result code {rc}")

    mqtt_client.connect(MQTT_BROKER)
    mqtt_client.loop_start()

    while True:
        try:
            temp, humidity = read_dht22()
            if temp is not None and humidity is not None:
                log(f"Temperature: {temp}°C, Humidity: {humidity}%")
                mqtt_client.publish(MQTT_TOPIC + "/temperature", str(temp))
                mqtt_client.publish(MQTT_TOPIC + "/humidity", str(humidity))
                watchdog_timer = WATCHDOG_TIMEOUT

            adc_value = read_adc(0)
            if adc_value is not None:
                log(f"ADC channel 0: {adc_value}")
                mqtt_client.publish(MQTT_TOPIC + "/adc0", str(adc_value))
                watchdog_timer = WATCHDOG_TIMEOUT

            time.sleep(300)

            # Process MQTT messages
            for topic, message in mqtt_client.get_check_msg():
                if topic.startswith(MQTT_TOPIC + "/pump"):
                    command = message.lower()
                    if command == "on" or command == "off":
                        control_pump(command)
                        log(f"Pump {command}")
                        watchdog_timer = WATCHDOG_TIMEOUT
                elif topic.startswith(MQTT_TOPIC + "/fan"):
                    command = message.lower()
                    if command == "on" or command == "off":
                        control_fan(command)
                        log(f"Fan {command}")
                        watchdog_timer = WATCHDOG_TIMEOUT
                elif topic.startswith(MQTT_TOPIC + "/light"):
                    command = message.lower()
                    if command == "on" or command == "off":
                        control_light(command)
                        log(f"Light {command}")
                        watchdog_timer = WATCHDOG_TIMEOUT
                elif topic.startswith(MQTT_TOPIC + "/status"):
                    mode = message.lower()
                    if mode == "online" or mode == "offline" or mode == "error" or mode == "synchronizing":
                        set_led_status(mode)
                        log(f"Status {mode}")
                        watchdog_timer = WATCHDOG_TIMEOUT

        except KeyboardInterrupt:
            log("KeyboardInterrupt received, cleaning up and exiting...")
            GPIO.cleanup()
            ADC.bus.close()
            mqtt_client.disconnect()
            mqtt_client.loop_stop()
            os._exit(0)
        except Exception as e:
            log(f"Error: {e}")
            set_led_status("error")
            watchdog_timer = WATCHDOG_TIMEOUT

if __name__ == "__main__":
    set_led_status("synchronizing")
    try:
        main()
    except:
        log("Unhandled exception, restarting...")
        os.execv(os.path.realpath(__file__), [sys.executable, __file__])

