import time
import queue
import argparse
import RPi.GPIO as GPIO
import spidev
import adafruit_mcp3008
import gpiozero

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = 1 / sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.mcp3008 = adafruit_mcp3008.MCP3008(spi_speed) if self.sensor_type == 'analog' else None
        self.gpio = GPIO.get_as_array() if self.sensor_type == 'digital' else None
        self.last_read = 0

    def _read_analog(self):
        if self.mcp3008 is None:
            return None
        data = self.mcp3008.read_channel(self.channels)
        return data[self.channels] >> 2

    def _read_digital(self):
        if self.gpio is None:
            return None
        return self.gpio[self.gpio_pins]

    def _debounce(self):
        time.sleep(0.1)

    def _log_event(self, event):
        if self.log_queue is not None:
            self.log_queue.put(f"SoundSensor {self.sensor_id}: {event}")

    def run(self):
        while True:
            reading = self._read_analog() if self.sensor_type == 'analog' else self._read_digital()
            if reading is not None:
                if self.sensor_type == 'digital':
                    event = 'event' if reading == 1 else 'no event'
                else:
                    event = 'event' if reading >= self.threshold else 'no event'
                self._debounce()
                self._log_event(event)
            time.sleep(self.sample_rate)

    def stop(self):
        if self.gpio is not None:
            GPIO.cleanup(self.gpio_pins)
        if self.mcp3008 is not None:
            self.mcp3008.deinit()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--sensor_type', choices=['digital', 'analog'], required=True)
