    parser.add_argument('--channels', nargs='+', type=int)
    parser.add_argument('--spi_speed', type=int)
    parser.add_argument('--sensor_ids', nargs='+', type=int)
    args = parser.parse_args()

    log_queue = queue.Queue() if args.log_file else None
    if args.log_file:
        try:
            with open(args.log_file, 'w') as log_file:
                log_file.write('')
        except Exception as e:
            print(f"Error opening log file: {e}")
            log_queue = queue.Queue()

    sound_sensors = []
    for sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed in zip(args.sensor_ids, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed):
        try:
            if sensor_type == 'digital':
                sensor = gpiozero.DigitalInputDevice(gpio_pins[0], pull_up=True)
            elif sensor_type == 'analog':
                i2c = spidev.SpiDev()
                i2c.open(0, 0)
                i2c.max_speed_hz = spi_speed
                sensor = adafruit_mcp3008.MCP3008(spi=i2c)
