import argparse
import time
import gpiozero
import RPi.GPIO as GPIO
import picamera2
import adafruit_datetime
import csv
import os
import sys
from PIL import Image
from pathlib import Path
import paho.mqtt.client as mqtt

def setup_gpio(pin_list):
    GPIO.setmode(GPIO.BCM)
    gpio_pins = set(pin_list)
    for pin in gpio_pins:
        try:
            GPIO.setup(pin, gpiozero.Input(pull_down=True))
            print(f"GPIO{pin} setup successful")
        except GPIO.ExpansionException as e:
            print(f"Error setting up GPIO{pin}: {e}")
            sys.exit(1)

def calibrate_sensors(gpio_pins, calibration_duration):
    baselines = {}
    for pin in gpio_pins:
        baselines[pin] = 0
        start_time = time.monotonic()
        total_high = 0
        for _ in range(int(calibration_duration * 1000)):
            if GPIO.input(pin):
                total_high += 1
        baselines[pin] = total_high / calibration_duration * 100
    return baselines

def set_thresholds(baselines):
    thresholds = {}
    for pin, baseline in baselines.items():
        thresholds[pin] = baseline + (baseline * 0.2)
    return thresholds

def main_loop(gpio_pins, thresholds, log_file, interval, picture_interval, camera):
    sensor_states = [0] * len(gpio_pins)
    short_window = int(interval * 1000)
    last_log_time = time.monotonic()
    last_pic_time = last_log_time

    while True:
        for pin, threshold in thresholds.items():
            if GPIO.input(pin):
                sensor_states[gpio_pins.index(pin)] = 1

        high_percentage = sum(sensor_states) / len(sensor_states) * 100
        log_line = adafruit_datetime.now().isoformat() + "," + ",".join(map(str, sensor_states)) + "\n"

        if time.monotonic() - last_log_time > interval:
            last_log_time += interval
            try:
                with open(log_file, "a") as f:
                    f.write(log_line)
                    f.flush()
            except Exception as e:
                print(f"Error writing to log file: {e}")
                print(log_line, file=sys.stderr)

            if camera:
                if time.monotonic() - last_pic_time > picture_interval:
                    last_pic_time += picture_interval
                    try:
                        image = capture_image(camera)
                        save_image(image, adafruit_datetime.now())
                    except Exception as e:
                        print(f"Error capturing image: {e}")

        time.sleep(short_window / 1000)

def capture_image(camera):
    config = camera.create_configuration(main={"format": "JPEG", "size": (1920, 1080)})
    camera.configure(config)
    camera.start_preview()
    camera.captured_image_cb = lambda img: save_image(img, adafruit_datetime.now())
    camera.capture_sequence_async([Image.new("RGB", (1920, 1080))], number_of_images=1)
    camera.stop_preview()
    return camera.capture_file("images/{}.jpg")

def save_image(image, timestamp):
    image_path = Path("images", f"{timestamp}.jpg")
    image.save(image_path)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_disconnect(client, userdata, rc):
    print(f"Disconnected with result code {rc}")

def on_log(client, userdata, level, buf):
