import board
import busio
from gpiozero import PIRMotionSensor
from adafruit_vl53l0x import VL53L0X
from paho.mqtt import client as mqtt_client

I2C_BUS = busio.I2C(board.SCL, board.SDA)
TOF_SENSOR = VL53L0X(I2C_BUS)

PIR_SENSORS = {
    11: "Zone 1",
    13: "Zone 2",
    15: "Zone 3"
}

LOG_FILE = "motion_log.txt"

def log_event(zone, distance, valid):
    log_data = f"{time.strftime('%Y-%m-%d %H:%M:%S')}, {zone}, Raw Distance: {distance}mm, Validation Status: {valid}\n"
    with open(LOG_FILE, "a") as log:
        log.write(log_data)

def debounce_pir(pir):
    last_state = False
    debounce_time = 2

    def debounced_callback(state):
        if state != last_state:
            last_state = state
            time.sleep(debounce_time)
            if last_state:
                on_motion(pir)

    pir.when_motion_started = debounced_callback
    pir.when_motion_stopped = debounced_callback

def on_motion(pir):
    for _ in range(3):
        try:
            distance = TOF_SENSOR.distance
            if distance > 0:
                moving_average = moving_average_filter(distance)
                if moving_average < 1000:
                    log_event(pir.pin, moving_average, True)
                else:
                    log_event(pir.pin, moving_average, False)
            time.sleep(0.1)
        except RuntimeError as e:
            logging.error(f"I2C bus error: {e}")

def moving_average_filter(values, size=5):
    return sum(values[-size:]) / size

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        logging.info("Connected to MQTT broker")
        client.subscribe("#")

def on_message(client, userdata, msg):
    logging.info(f"Received message: {msg.topic}: {msg.payload.decode()}")

def setup_logging():
    log_dir = "/home/pi"
    if not os.path.exists(log_dir):
        os.makedirs(log_dir)
    log_file_path = os.path.join(log_dir, LOG_FILE)
    logging.basicConfig(filename=log_file_path, level=logging.INFO, format="%(asctime)s %(message)s")

def main():
    setup_logging()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message
    mqtt_client.create_default_keepalive(60)

    mqtt_client.loop_start()

    for pin, zone in PIR_SENSORS.items():
        pir = PIRMotionSensor(pin)
        debounce_pir(pir)
        pir.wait_for_motion()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Received SIGTERM, shutting down...")

    mqtt_client.loop_stop()
    for pir in PIR_SENSORS.values():
        pir.stop()
    TOF_SENSOR.stop()
    TOF_SENSOR.close()
    os.fsync(open(LOG_FILE, "fsync"))
    os.close(os.open(LOG_FILE, os.O_RDWR))

if __name__ == "__main__":
    atexit.register(main)
    main()

