                if no_detection_count > 30:
                    os.execv(sys.executable, [sys.executable] + sys.argv)
        no_detection_count = 0
        time.sleep(1)

def init_camera(camera_device):
    try:
        i2c = busio.I2C(sda=wiringpi.wiringPiI2CData(2), scl=wiringpi.wiringPiI2CData(3))
        camera = picamera2.Camera(i2c, sensor_i2c_addr=0x3a)
        camera.start_preview()
        return camera
    except Exception as e:
