                        cameras[camera] = None
                        working_cameras.remove(camera)

            if working_cameras != cameras:
                cameras = {cam: init_camera(cam) for cam in camera_devices}
                working_cameras = set(cameras)

            if cameras and camera_devices != working_cameras:
