import psutil
import paho.mqtt.client as mqtt

class Led:
    def __init__(self, gpio_pin):
        self.gpio_pin = gpio_pin
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.gpio_pin, GPIO.OUT)

    def on(self):
        GPIO.output(self.gpio_pin, GPIO.HIGH)

    def off(self):
        GPIO.output(self.gpio_pin, GPIO.LOW)

class CpuStatsLcd:
    def __init__(self, i2c_bus=1, lcd_width=16, lcd_height=2):
        self.i2c_bus = I2C.get_bus(i2c_bus)
        self.lcd = adafruit_ssd1306.SSD1306_I2C(lcd_width, lcd_height, self.i2c_bus)

    def display_cpu_usage(self, cpu_usage, cpu_temp):
        self.lcd.fill(0)
        self.lcd.text('CPU: {}% {}°C'.format(cpu_usage, cpu_temp), 0, 0, 1)
        self.lcd.show()

class CpuStats:
    def __init__(self):
        self.cpu_percent = psutil.cpu_percent()
        self.cpu_temp = psutil.sensors_temperature('cpu')[0].current
        self.lcd = CpuStatsLcd()
        self.leds = [Led(17), Led(18), Led(23), Led(27), Led(22)]
        self.led_index = 0
        self.running = True

    def update_display(self):
        while self.running:
            try:
                self.cpu_percent = psutil.cpu_percent()
                self.cpu_temp = psutil.sensors_temperature('cpu')[0].current
                self.lcd.display_cpu_usage(self.cpu_percent, self.cpu_temp)
                time.sleep(1)
            except (psutil.NoSuchProcess, psutil.NoSuchFileOrDirectory):
                pass

    def update_led(self):
        while self.running:
            try:
                self.leds[self.led_index].on()
                time.sleep(1)
                self.leds[self.led_index].off()
                self.led_index = (self.led_index + 1) % len(self.leds)
                time.sleep(0.5)
            except Exception as e:
                print(f"Error in LED update: {e}")

