import time
import RPi.GPIO as GPIO
import board
import adafruit_vl53l0x
import adafruit_hcsr04
import picamera2
import paho.mqtt.client as mqtt

# I2C and GPIO setup
i2c = board.I2C()
GPIO.setmode(GPIO.BCM)

# VL53L0X water level sensor
water_sensor = adafruit_vl53l0x.VL53L0X(i2c, address=0x29)

# HC-SR04 nutrient level sensor
trig_pin = GPIO.GPIO(23, GPIO.OUT)
echo_pin = GPIO.GPIO(24, GPIO.IN)
nutrient_sensor = adafruit_hcsr04.HCSR04(trigger_pin, echo_pin)

# Pumps
water_pump_pin = GPIO.GPIO(17, GPIO.OUT)
nutrient_pump_pin = GPIO.GPIO(27, GPIO.OUT)

def handle_i2c_error(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except OSError as e:
            print(f"I2C error: {e}")
            return -1
    return wrapper

def handle_gpio_error(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except GPIO.GPIOException as e:
            print(f"GPIO error: {e}")
            return -1
    return wrapper

def handle_sensor_error(func):
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        if result == -1:
            print("Sensor error")
        return result

@handle_i2c_error
def read_water_level():
    return water_sensor.distance

@handle_gpio_error
def read_nutrient_level():
    trig_pin.toggle()
    time.sleep(0.00001)
    trig_pin.toggle()

    start_time = time.monotonic()
    while True:
        if GPIO.input(echo_pin):
            end_time = time.monotonic()
            time_elapsed = end_time - start_time
            if time_elapsed > 0.00003:
                break

    distance = (time_elapsed * 17150) / 2
    return distance

def control_water_pump():
    while True:
        water_level = read_water_level()
        if water_level == -1:
            return

        if water_level < 100:
            water_pump_pin.on()
        elif water_level >= 150:
            water_pump_pin.off()
            break

        time.sleep(1)

def control_nutrient_pump():
    nutrient_level = read_nutrient_level()
    if nutrient_level == -1:
        return

    if nutrient_level < 5:
        nutrient_pump_pin.on()
        time.sleep(5)
        nutrient_pump_pin.off()

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_disconnect(client, userdata, rc):
    print(f"Disconnected with result code {rc}")

def on_publish(client, userdata, mid):
    print(f"Published message on topic {mid}")

def publish_sensor_data(client):
    while True:
        water_level = read_water_level()
        if water_level == -1:
            return

        nutrient_level = read_nutrient_level()
        if nutrient_level == -1:
            return

        water_level_mm = int(water_level * 10)
        nutrient_level_cm = int(nutrient_level / 10)

        client.publish("water_level", water_level_mm)
        client.publish("nutrient_level", nutrient_level_cm)

        time.sleep(1)

def main():
    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_disconnect = on_disconnect
    mqtt_client.on_publish = on_publish

    mqtt_client.connect("mqtt.example.com", 1883, 60)
    mqtt_client.loop_start()

    try:
        control_water_pump()
        control_nutrient_pump()
        publish_sensor_data(mqtt_client)
    except KeyboardInterrupt:
        water_pump_pin.off()
        nutrient_pump_pin.off()
        GPIO.cleanup()
        i2c.deinit()
        mqtt_client.loop_stop()

if __name__ == "__main__":
    main()

