import time
import logging
import gpiozero
import smbus
import struct
from adafruit_crc import CRC8
from paho.mqtt import client as mqtt_client

class DHT20:
    def __init__(self, bus=1, address=0x2c):
        self.bus = smbus.SMBus(bus)
        self.address = address
        self.logger = logging.getLogger(__name__)
        self.logger.info("Initializing DHT20 sensor...")
        self.wait_for_stabilization()
        self.check_status()

    def wait_for_stabilization(self):
        self.logger.debug("Waiting for 0.5s for power stabilization...")
        time.sleep(0.5)

    def check_status(self):
        status = self.read_byte(0)
        expected_status = 0b11101000
        if status != (expected_status & (0xFF - self.address)):
            self.logger.error("Status check failed. Expected 0b11101000, got 0x{:02X}".format(status))
            raise Exception("Status check failed")

    def read_byte(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except IOError as e:
            self.logger.error("I2C bus error: {}".format(e))
            raise Exception("I2C bus error")

    def read_data(self):
        self.logger.debug("Reading data from DHT20 sensor...")
        data = self.bus.read_i2c_block_data(self.address, 5)
        if len(data) != 5:
            self.logger.error("Unexpected number of bytes read from DHT20 sensor.")
            raise Exception("Unexpected number of bytes read")

        humidity_raw = struct.unpack(">H", data[1:4])[0]
        temperature_raw = struct.unpack(">H", data[3:6])[0]
        crc = data[6]
        crc_calculated = CRC8(0x31, initial=0x00).calc(data[0:6])
        if crc != crc_calculated:
            self.logger.warning("CRC checksum error. Expected 0x{:02X}, got 0x{:02X}".format(crc_calculated, crc))
            return (None, None, True)

        humidity = humidity_raw // 10
        temperature = (temperature_raw & 0x7FFF) * 175 / 65536 - 45
        return (temperature, humidity, False)

    def poll_status(self):
        self.logger.debug("Polling DHT20 sensor status...")
        max_retries = 5
        timeout = 0.1
        while True:
            status = self.read_byte(0)
            if not (status & (1 << 7)):
                break
            if max_retries > 0:
                self.logger.warning("Status bit 7 not set. Retrying...")
                time.sleep(2)
                max_retries -= 1
            else:
                self.logger.error("Timeout waiting for DHT20 sensor to send data.")
                return False
        return self.read_data()

    def __del__(self):
        self.bus.close()

    def cleanup(self):
        self.bus.close()

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        client.connected_flag = True

def on_disconnect(client, userdata, rc):
    client.connected_flag = False

def on_publish(client, userdata, mid):
    print("Data published.")

def on_log(client, userdata, level, msg):
    print(msg)

def publish_data(client, temperature, humidity, crc_error_flag):
    if not crc_error_flag:
        client.publish("temperature", str(temperature))
        client.publish("humidity", str(humidity))

if __name__ == "__main__":
    logging.basicConfig(level=logging.DEBUG)
    mqtt_client = mqtt_v2_client.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_disconnect = on_disconnect
    mqtt_client.on_publish = on_publish
    mqtt_client.on_log = on_log
    mqtt_client.connect("mqtt.example.com", 1883, 60)
    dht20 = DHT20()
    while True:
        if dht20.poll_status():
            temperature, humidity, crc_error_flag = dht20.poll_status()
            if temperature is not None:
                publish_data(mqtt_client, temperature, humidity, crc_error_flag)
        time.sleep(10)

