import adafruit_dht.DHT22
import adafruit_logging_backend
import paho.mqtt.client as mqtt
from datetime import timedelta
from aiohttp import web
from aiohttp_logging import setup_logging

# Set up logging
log_format = "%(asctime)s [%(levelname)s] %(message)s"
logging.basicConfig(format=log_format, level=logging.INFO)
handler = logging.handlers.RotatingFileHandler(
    filename=os.getenv("LOG_FILE", "greenhouse.log"),
    maxBytes=1048576, backupCount=5
)
handler.setFormatter(logging.Formatter(log_format))
logging.getLogger().addHandler(handler)

class Greenhouse:
    def __init__(self):
        self.outlet_configurations = self.load_config()
        self.gpio_transmitter_pin = self.outlet_configurations["gpio_transmitter_pin"]
        self.gpio_dht22_pin = self.outlet_configurations["gpio_dht22_pin"]
        self.dht22_read_interval = self.outlet_configurations["dht22_read_interval"]
        self.log_file = self.outlet_configurations["log_file"]

        self.dht22 = adafruit_dht.DHT22(self.gpio_dht22_pin)
        self.dht_last_read = time.monotonic()

        self.outlet_states = {outlet: {"state": False, "last_transmit": 0} for outlet in self.outlet_configurations["outlets"]}

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.gpio_transmitter_pin, GPIO.OUT)
        GPIO.setup(self.gpio_dht22_pin, GPIO.IN)

        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_mqtt_connect
        self.mqtt_client.on_message = self.on_mqtt_message

        self.sensor_task = asyncio.create_task(self.sensor_reading_loop())

    def load_config(self):
        try:
            with open("greenhouse_config.json", "r") as f:
                return json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            return {
                "gpio_transmitter_pin": GPIO17,
                "gpio_dht22_pin": GPIO4,
                "dht22_read_interval": 60,
                "log_file": "greenhouse.log",
                "outlets": [
                    {"system_code": "10101", "unit_codes": ["1", "2", "3"]},
                ],
            }

    def on_mqtt_connect(self, client, userdata, flags, rc):
        if rc == 0:
            logging.info("Connected to MQTT broker")
            self.mqtt_client.subscribe("#")

    def on_mqtt_message(self, client, userdata, msg):
        command, outlet = msg.topic.split("/")[-2:]
        if command == "on" or command == "off":
            self.set_outlet_state(outlet, command == "on")

    async def sensor_reading_loop(self):
        while True:
            if time.monotonic() - self.dht_last_read > self.dht22_read_interval:
                try:
