def log(message):
    with open("greenhouse.log", "a") as log_file:
        log_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")

def read_sensors():
    try:
        temp_humidity = [None] * 2
        for i, dht_device in enumerate(dht_devices):
            temp, humidity = dht_device.temperature, dht_device.humidity
            if temp is not None and humidity is not None:
                temp_humidity[i] = (temp, humidity)
            else:
                log(f"Failed to read sensor {i + 1}")
                temp_humidity[i] = (dht_devices[i].last_temperature, dht_devices[i].last_humidity)
        return temp_humidity
    except Exception as e:
        log(f"Error reading sensors: {e}")
        return [(None, None), (None, None)]

def actuate_vent():
    try:
        GPIO.setup(VENT_PIN, GPIO.OUT)
        GPIO.output(VENT_PIN, GPIO.HIGH)
        time.sleep(5)
        GPIO.output(VENT_PIN, GPIO.LOW)
        log(f"Actuated vent at {time.strftime('%Y-%m-%d %H:%M:%S')}")
    except Exception as e:
        log(f"Error actuating vent: {e}")
        GPIO.cleanup()
        raise
    finally:
        GPIO.cleanup(VENT_PIN)

def check_limit_switch():
    try:
        state = GPIO.input(LIMIT_PIN)
        if state:
            log(f"Limit switch triggered HIGH at {time.strftime('%Y-%m-%d %H:%M:%S')}")
            return True
        return False
    except Exception as e:
        log(f"Error checking limit switch: {e}")
        return False

