        mqtt_client.loop_start()

        while True:
            try:
                temp_humidity = read_sensors()
                if any(t is None or h is None for t, h in temp_humidity):
                    continue

                for i, (t, h) in enumerate(temp_humidity):
                    if t is None or h is None:
                        t, h = temp_humidity[0][i]
                    if t > MAX_TEMP:
                        log(f"Opening vent due to high temperature ({t}°C) at {time.strftime('%Y-%m-%d %H:%M:%S')}")
                        actuate_vent()
                        if not check_limit_switch():
                            log(f"Vent actuation timed out at {time.strftime('%Y-%m-%d %H:%M:%S')}")
                        else:
                            log(f"Vent actuation successful at {time.strftime('%Y-%m-%d %H:%M:%S')}")
                    if h is not None and h < MIN_HUMIDITY:
                        log(f"Opening vent due to low humidity ({h}%) at {time.strftime('%Y-%m-%d %H:%M:%S')}")
