    readings = []
    for _ in range(8):
        try:
            pressure = bmp280.pressure
            readings.append(pressure)
        except ValueError:
            print("Error reading BMP280 pressure, continuing...")
    if len(readings) < 6:
        print("Not enough valid readings for baseline pressure calculation.")
        return None
    return sum(readings[2:]) / (len(readings) - 2)

