    if baseline_pressure is None:
        return None
    try:
        sea_level_pressure = 101325.0  # Standard sea level pressure in Pa
        temperature = bmp280.temperature
        pressure = bmp280.pressure
        altitude = (sea_level_pressure * (1 - (pressure / baseline_pressure)**(1/5.255)) * (temperature + 273.15 / 273.15)) * 100
        return altitude
    except OSError:
        print("Error reading BMP280 data, continuing...")
        return None

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_publish(client, userdata, mid):
