        print("Error connecting to MQTT broker, exiting...")
        return

    while True:
        try:
            altitude = get_altitude(baseline_pressure)
            if altitude is not None:
                client.publish(mqtt_topic, str(altitude))
        except OSError:
            print("Error reading BMP280 data, continuing...")

        time.sleep(1)

    client.disconnect()

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("Exiting gracefully...")
        bmp280.deinit()
        client.disconnect()

