class PwmFan:
    def __init__(self, pin):
        self.pin = pin
        self.pwm = gpiozero.PWM(self.pin, frequency=100)
        self.pwm.start(0)
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.pin, GPIO.OUT)

    def set_duty_cycle(self, duty_cycle):
        self.pwm.duty_cycle = duty_cycle

    def stop(self):
        self.pwm.stop()
        GPIO.cleanup(self.pin)

class TemperatureSensor:
    def __init__(self, sensor_type=adafruit_dht.DHT22):
        self.sensor = sensor_type(GPIO.BCM.GPIO17, GPIO.BCM.GPIO18)

    def read_temperature(self):
        try:
            self.sensor.measure_temperature()
            return self.sensor.temperature
        except Exception as e:
            print(f"Error reading temperature: {e}")
            return None

class FanController:
    def __init__(self, fan, temperature_sensor):
        self.fan = fan
        self.temperature_sensor = temperature_sensor
        self.target_temperature = 70
        self.current_temperature = None
        self.fan_speed_steps = [0, 10, 25, 50, 75, 100]

    def run(self):
        while True:
            self.current_temperature = self.temperature_sensor.read_temperature()
            if self.current_temperature is not None:
                fan_speed = self.get_fan_speed(self.current_temperature)
                self.fan.set_duty_cycle(self.fan_speed_steps[fan_speed])
                self.log_temperature_and_fan_speed()
            time.sleep(5)

    def get_fan_speed(self, temperature):
        if temperature < self.target_temperature - 5:
            return 0
        elif temperature < self.target_temperature:
            return 1
        elif temperature < self.target_temperature + 5:
            return 2
        elif temperature < self.target_temperature + 10:
            return 3
        elif temperature < self.target_temperature + 15:
            return 4
        else:
            return 5

    def log_temperature_and_fan_speed(self):
        log_file = open("fan_log.txt", "a")
        log_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')}, {self.current_temperature}, {self.fan.duty_cycle}\n")
        log_file.close()

