import time
import logging
import gpiozero
import Adafruit_DHT
import w1thermometer
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(filename='hydroponics_data.log', level=logging.INFO,
                    format='%(asctime)s - %(message)s')

# Initialize sensors and LED
dht_sensor = Adafruit_DHT.DHT22
ds18b20 = w1thermometer.DS18B20(w1_bus_gpio=4)
led = gpiozero.LED(17)

def on_connect(client, userdata, flags, rc):
    logging.info(f"Connected to MQTT broker with result code {rc}")

def on_disconnect(client, userdata, flags, rc):
    logging.info(f"Disconnected from MQTT broker with result code {rc}")

def on_publish(client, userdata, mid):
    logging.info(f"Published message with mid {mid}")

def on_subscribe(client, userdata, mid, granted_qos):
    logging.info(f"Subscribed to topic {mid}")

def on_message(client, userdata, msg):
    logging.info(f"Received message '{msg.payload.decode()}' on topic '{msg.topic}'")

def read_sensors():
    try:
        humidity, temperature = Adafruit_DHT.read_retry(dht_sensor, 4)
        if humidity is not None and temperature is not None:
            return humidity, temperature
        else:
            logging.warning(f"Failed to read DHT22 sensor data: humidity={humidity}, temperature={temperature}")
    except Exception as e:
        logging.error(f"Error reading DHT22 sensor: {e}")

    try:
        temperature = ds18b20.get_temperature()
        if temperature is not None:
            return None, temperature
        else:
            logging.warning(f"Failed to read DS18B20 sensor data: temperature={temperature}")
    except Exception as e:
        logging.error(f"Error reading DS18B20 sensor: {e}")

    return None, None

def main():
    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_disconnect = on_disconnect
    mqtt_client.on_publish = on_publish
    mqtt_client.on_subscribe = on_subscribe
    mqtt_client.on_message = on_message

    mqtt_client.connect("mqtt.example.com", 1883, 60)
    mqtt_client.loop_start()

    while True:
        try:
            humidity, temperature = read_sensors()
            if humidity is not None:
                logging.info(f"DHT22: Humidity={humidity:.2f}%, Temperature={temperature:.2f}°C")
                mqtt_client.publish("hydroponics/dht22/humidity", humidity, qos=1)
                mqtt_client.publish("hydroponics/dht22/temperature", temperature, qos=1)

            if temperature is not None:
                logging.info(f"DS18B20: Temperature={temperature:.2f}°C")
                mqtt_client.publish("hydroponics/ds18b20/temperature", temperature, qos=1)

            if temperature is not None and temperature > 30:
                led.on()
            else:
                led.off()

            time.sleep(5)
        except KeyboardInterrupt:
            led.off()
            mqtt_client.disconnect()
            mqtt_client.loop_stop()
            logging.info("Exiting...")
            break

if __name__ == "__main__":
    main()

