    with open("humidity_log.txt", "a") as file:
        file.write(f"{dt.datetime.now().isoformat()}, {data}\n")

def classify_humidity(humidity):
    if humidity < 30:
        return "too_dry"
    elif humidity < 40:
        return "dry"
    elif humidity < 60:
        return "comfortable"
    else:
        return "too_humid"

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker!")
        client.publish("humidity/status", "Connected")
    else:
        print(f"Failed to connect, return code {rc}")

def on_publish(client, userdata, mid):
    print(f"Delivered message with mid: {mid}")

