    try:
        i2c = I2C(I2C_BUS)
        bme280 = BME280(i2c, I2C_ADDR)
        bme280.sea_level_pressure = 1013.25

        mqtt_client = mqtt_client.Client()
        mqtt_client.on_connect = on_connect
        mqtt_client.on_publish = on_publish

        mqtt_client.connect("mqtt.example.com", 1883, 60)

        for _ in range(5):
            try:
                humidity = bme280.humidity
                humidity_band = classify_humidity(humidity)
                log_to_file(f"{humidity}, {humidity_band}")
                mqtt_client.publish(f"humidity/humidity_{humidity_band}", str(humidity))
                print(f"Humidity: {humidity}, Band: {humidity_band}")
