# SPI bus configuration
SPI_PORT = 0
SPI_DEVICE = 0
SPI_BAUD = 16000000

# GPIO pins configuration
RST = 18
DC = 22
LED = 23

# Display configuration
WIDTH = 128
HEIGHT = 128

def init_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_PORT, SPI_DEVICE)
        spi.max_speed_hz = SPI_BAUD
        return spi
    except Exception as e:
        print(f"Error initializing SPI bus: {e}")
        GPIO.cleanup()
        exit(1)

def init_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RST, GPIO.OUT)
        GPIO.setup(DC, GPIO.OUT)
        GPIO.setup(LED, GPIO.OUT)
        return GPIO
    except Exception as e:
        print(f"Error initializing GPIO pins: {e}")
        GPIO.cleanup()
        exit(1)

def init_display(spi, gpio):
    try:
        display = ST7735.ST7735(spi, cs=DC, rst=RST, backlight=LED, width=WIDTH, height=HEIGHT)
        display.begin()
        return display
    except Exception as e:
        print(f"Error initializing display: {e}")
        GPIO.cleanup()
        exit(1)

def draw_char(display, char, x, y, color):
    try:
        font = adafruit_terminal_font.TerminalFont().font_data
        for i in range(len(font)):
            if font[i] == char:
                for j in range(8):
                    for k in range(8):
                        if font[i + j * 8 + k] & (1 << (7 - k)):
                            display.pixel(x + k, y + j, color)
    except Exception as e:
        print(f"Error drawing character: {e}")

def draw_text(display, text, x, y, color, font_size=1):
    try:
        font = adafruit_terminal_font.TerminalFont(font_size)
        for i in range(len(text)):
            char = text[i]
            if char == '\n':
                y += font_size
                x = 0
                continue
            draw_char(display, char, x, y, color)
            x += font.width
    except Exception as e:
        print(f"Error drawing text: {e}")

def draw_rectangle(display, x, y, width, height, color):
    try:
        for i in range(height):
            for j in range(width):
                display.pixel(x + j, y + i, color)
    except Exception as e:
        print(f"Error drawing rectangle: {e}")

def draw_lines(display, color):
    try:
        for x in range(WIDTH):
            for y in range(HEIGHT):
                if (x + y) % 2 == 0:
                    display.line((x, 0, x, HEIGHT), color)
    except Exception as e:
        print(f"Error drawing lines: {e}")

def sigint_handler(signal, frame):
    print("Received SIGINT/SIGTERM, cleaning up...")
    GPIO.cleanup()
    spi.close()
    exit(0)

if __name__ == "__main__":
    spi = init_spi()
    gpio = init_gpio()
    display = init_display(spi, gpio)

    # Display ASCII characters 32-255
