        draw_char(display, char, 0, 0, (255, 255, 255))
        time.sleep(0.01)

    # Display "Hello,World!" and "TFT144"
    draw_text(display, "Hello,World!", 0, 16, (255, 0, 0))
    time.sleep(2)
    draw_text(display, "TFT144", 0, 32, (0, 255, 0))
    time.sleep(2)

    # Draw rectangles and lines
    draw_rectangle(display, 0, 0, WIDTH, HEIGHT // 2, (255, 0, 0))
    draw_rectangle(display, 0, HEIGHT // 2, WIDTH, HEIGHT // 2, (0, 0, 0))
    draw_lines(display, (0, 255, 0))
    time.sleep(3)

    # Install SIGINT/SIGTERM handler
    signal.signal(signal.SIGINT, sigint_handler)
    signal.signal(signal.SIGTERM, sigint_handler)

    # Keep the program running
    while True:
        pass

