from typing import Optional

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int = 0):
        if pin_number not in range(32):
            raise ValueError("Invalid pin number. Valid pins are 0-31.")
        if initial_value not in (0, 1):
            raise ValueError("Initial value must be 0 or 1.")

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(pin_number, GPIO.OUT)
            GPIO.output(pin_number, initial_value)
        except GPIO.GPIOFatalError:
            raise RuntimeError("Unable to reach the underlying GPIO driver daemon.")

        self._pin = pin_number
        self._value = initial_value

    def set_value(self, value: int):
        if value not in (0, 1):
            raise ValueError("Value must be 0 or 1.")
        try:
            GPIO.output(self._pin, value)
            self._value = value
        except GPIO.GPIOFatalError:
            pass

    def shutdown(self):
        try:
            GPIO.cleanup(self._pin)
        except GPIO.GPIOFatalError:
            pass

if __name__ == "__main__":
    output_pin = OutputPin(17, 1)
    try:
        for _ in range(10):
            output_pin.set_value(1)
            time.sleep(0.5)
            output_pin.set_value(0)
            time.sleep(0.5)
        output_pin.shutdown()
    except KeyboardInterrupt:
        output_pin.shutdown()

