            if self.prev_clk_state is not None:
                direction = self.prev_clk_state ^ current_dt_state
                if direction:
                    self.counter += direction * 1
                    if self.callback:
                        try:
                            self.callback(self.counter)
                        except Exception as e:
                            print(f"Error in callback: {e}")

        self.prev_clk_state = GPIO.input(self.clk_pin)

    def cleanup(self):
        self.debouncer.stop()
        GPIO.cleanup(self.dt_pin)
        GPIO.cleanup(self.clk_pin)

class Debouncer:
    def __init__(self, debounce_time):
        self.debounce_time = debounce_time
        self.last_edge_time = 0
        self.edge_count = 0

    def start(self, callback):
        self.callback = callback
        self.timer = GPIO.add_event_detect(self.callback_pin, GPIO.BOTH, callback=self.on_edge, bouncetime=self.debounce_time)

    def stop(self):
        GPIO.remove_event_detect(self.callback_pin)

    def on_edge(self, channel):
        current_time = time.monotonic()
        if current_time - self.last_edge_time > self.debounce_time:
            self.last_edge_time = current_time
            self.edge_count += 1
            self.callback(self.edge_count)

