from paho.mqtt import client as mqtt_client

# Grid dimensions
GRID_WIDTH = 5
GRID_HEIGHT = 5
START_X = 0
START_Y = 0
END_X = 4
END_Y = 4

# LED configuration
LED_GPIO = 18
LED_RESISTOR = 330
LED = None

def setup_led():
    global LED
    try:
        LED = gpiozero.LED(LED_GPIO)
    except RuntimeError:
        print(f"Warning: No GPIO{LED_GPIO} found. LED functionality will be disabled.")

def drive_led(state):
    if LED:
        if state:
            LED.on()
            time.sleep(2)
            LED.off()
        else:
            blink_rate = 0.5
            for _ in range(3):
                LED.on()
                time.sleep(blink_rate)
                LED.off()
                time.sleep(blink_rate)

def create_grid(grid_data):
    G = nx.Graph()
    for y in range(GRID_HEIGHT):
        for x in range(GRID_WIDTH):
            if grid_data[y][x] == 1:
                G.add_node((x, y), obstacle=True)
            else:
                G.add_node((x, y), obstacle=False)
                if (x, y) == (START_X, START_Y):
                    G.node[(x, y)]["start"] = True
                if (x, y) == (END_X, END_Y):
                    G.node[(x, y)]["end"] = True
    return G

def bfs(graph, start_node):
    visited = set()
    queue = [start_node]
    path = []

    while queue:
        current_node = queue.pop(0)
        if current_node not in visited:
            visited.add(current_node)

            if graph.node[current_node]["end"]:
                path += [current_node]
                break

            for neighbor in graph.neighbors(current_node):
                if neighbor not in visited:
                    queue.append(neighbor)

    return path[::-1]

def main():
    setup_led()

    # Assuming grid data is provided as a 2D list
    grid_data = [
        [0, 0, 0, 0, 1],
        [0, 0, 0, 1, 0],
        [0, 0, 1, 0, 0],
        [0, 1, 0, 0, 0],
        [1, 0, 0, 0, 0]
    ]

    try:
        graph = create_grid(grid_data)
        path = bfs(graph, (START_X, START_Y))

        if path and path[-1] == (END_X, END_Y):
            drive_led(True)
            print(f"Path length: {len(path) - 1}")
        else:
            drive_led(False)
            print("No path found.")

    except KeyboardInterrupt:
        drive_led(False)
        print("Interrupted.")

    except Exception as e:
        drive_led(False)
        print(f"Error: {e}")

    finally:
        if LED:
            LED.off()
        Camera.unload_all()

if __name__ == "__main__":
    main()

import time
import sys
import signal
import csv
import json
import board
import busio
from adafruit_mpu6050.mpu6050 import MPU6050
from gpiozero import I2C
from paho.mqtt import client as mqtt_client

I2C_BUS = 1
SDA = 2
SCL = 3
ANOMALY_THRESHOLD = 50.0

def i2c_retry(func):
    attempts = 3

    def wrapper(*args, **kwargs):
        while attempts > 0:
            try:
                return func(*args, **kwargs)
            except IOError:
                attempts -= 1
                time.sleep(1)
        raise Exception("I2C initialization failed after all retries")

    return wrapper

@i2c_retry
def init_i2c():
    i2c = I2C(I2C_BUS, SDA, SCL)
    return busio.I2C(board.SCL, board.SDA)

@i2c_retry
def init_sensor():
    i2c = init_i2c()
    sensor = MPU6050(i2c)
    sensor.gyro = True
    sensor.accel = True
    return sensor

def log_to_csv(data, filename):
    with open(filename, 'a', newline='') as csvfile:
        fieldnames = ['timestamp', 'raw_x', 'raw_y', 'raw_z', 'filtered_x', 'filtered_y', 'filtered_z', 'anomaly']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

        if csvfile.tell() == 0:
            writer.writeheader()

        writer.writerow(data)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker")
        client.subscribe("#")

def on_message(client, userdata, msg):
    print(f"Received message: {msg.topic}: {msg.payload.decode()}")

def main():
    if len(sys.argv) < 4:
        print("Usage: python gyro_data_collector.py --sample_rate=<Hz> --window_size=<samples> [--cloud_enabled]")
        sys.exit(1)

    sample_rate = int(sys.argv[sys.argv.index("--sample_rate=") + 1)
    window_size = int(sys.argv[sys.argv.index("--window_size=") + 1)
    cloud_enabled = "--cloud_enabled" in sys.argv

    if sample_rate not in range(1, 51) or window_size not in range(3, 16):
        print("Invalid sample rate or window size")
        sys.exit(1)

    sensor = init_sensor()
    gyro_scale = 131.0 / 32768.0

    sample_interval = 1.0 / sample_rate
    last_timestamp = time.monotonic()
    sample_count = 0
    data_window = [None] * window_size
    anomaly_count = 0

    try:
        mqtt_client = mqtt_client.Client()
        mqtt_client.on_connect = on_connect
        mqtt_client.on_message = on_message

        if cloud_enabled:
            mqtt_client.connect("mqtt.example.com", 1883, 60)

        while True:
            try:
                gyro_data = sensor.gyro.acceleration
                timestamp = time.monotonic()

                data_window[sample_count % window_size] = {
                    "timestamp": timestamp,
                    "raw_x": gyro_data[0],
                    "raw_y": gyro_data[1],
                    "raw_z": gyro_data[2],
                    "filtered_x": sum(data_window[i % window_size][0] for i in range(sample_count - window_size, sample_count + 1)) / (window_size + 1),
                    "filtered_y": sum(data_window[i % window_size][1] for i in range(sample_count - window_size, sample_count + 1)) / (window_size + 1),
                    "filtered_z": sum(data_window[i % window_size][2] for i in range(sample_count - window_size, sample_count + 1)) / (window_size + 1),
                    "anomaly": any(abs(gyro_data[i] - data_window[(sample_count - 1) % window_size][i]) / sample_interval / gyro_scale > ANOMALY_THRESHOLD for i in range(3))
                }

                if cloud_enabled:
                    mqtt_client.publish(f"gyro_data_{sample_count}", json.dumps(data_window[sample_count]))

                log_to_csv(data_window[sample_count], f"gyro_data_{int(timestamp)}".replace(".", "_"))

                if data_window[sample_count]["anomaly"]:
                    anomaly_count += 1

                sample_count += 1
                last_timestamp += sample_interval
                time.sleep(sample_interval)

            except Exception as e:
                print(f"Error: {e}")
                if cloud_enabled:
                    mqtt_client.disconnect()
                break

        if cloud_enabled:
            mqtt_client.disconnect()

    except KeyboardInterrupt:
        print("Interrupted, cleaning up resources...")
        if cloud_enabled:
            mqtt_client.disconnect()

    finally:
        sensor.deinit()

if __name__ == "__main__":
    main()

