        self.gps = gps.GPS(mode=gps.WATCH_ENABLE | gps.WATCH_NEWSTYLE)
        self.gps.send_command(gps.PMTK_SET_NMEA_OUTPUT_RMCGGA)
        self.gps.send_command(gps.PMTK_SET_NMEA_UPDATE_1HZ)
