        self.gps.serial.parity = serial.PARITY_NONE
        self.gps.serial.stopbits = serial.STOPBITS_ONE
        self.gps.serial.rts = True
        self.gps.serial.tx = self.i2c.get_port(14)
        self.gps.serial.rx = self.i2c.get_port(15)
        self.gps.serial.reset_input_buffer()

    async def read(self):
