        return await SimulatedGPS().read()

async def handle_command(client_socket, gps_device):
    try:
        data = await client_socket.recv(1024)
        command = data.decode().strip().lower()
        if command == "start":
            gps_device.start()
        elif command == "stop":
            gps_device.stop()
        elif command == "report":
            position = await read_gps_position(gps_device)
            await client_socket.sendall(position.encode())
        else:
