import time
import RPi.GPIO as GPIO
import gpiozero
import adafruit_motor
import adafruit_motor.control
import adafruit_74hc595
import paho.mqtt.client as mqtt

class MotorShield:
    def __init__(self):
        self.shifter = adafruit_74hc595. SevenSegmentShiftRegister(
            clock=GPIO.BCM.IN,
            latch=GPIO.BCM(11),
            data=GPIO.BCM(10)
        )
        self.motors = {}
        self.directions = {
            1: (0b00000010, 0b00001000),
            2: (0b00000001, 0b00000100)
        }

    def add_motor(self, motor_id, pwm_pin):
        self.motors[motor_id] = adafruit_motor.servo.Servo(pwm_pin)

    def start(self, motor_id):
        direction, _ = self.directions[motor_id]
        self.shifter.send([direction])
        self.motors[motor_id].throttle = 0.5

    def stop(self, motor_id):
        self.motors[motor_id].throttle = 0

    def change_duty_cycle(self, motor_id, duty_cycle):
        self.motors[motor_id].throttle = duty_cycle

    def stop_all_motors(self):
        for motor in self.motors.values():
            motor.throttle = 0

    def __enter__(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(13, GPIO.OUT)
        GPIO.setup(12, GPIO.OUT)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.stop_all_motors()
        GPIO.cleanup()

def on_log(client, userdata, level, msg):
    print(f"[{level}] {msg}")

def motor_control():
    mqtt_client = mqtt.Client()
    mqtt_client.on_log = on_log
    mqtt_client.connect("localhost", 1883, 60)

    with MotorShield() as shield:
        shield.add_motor(1, 13)
        shield.add_motor(2, 12)
        shield.start(1)
        shield.start(2)
        time.sleep(5)
        shield.change_duty_cycle(1, 0.25)
        time.sleep(5)
        shield.stop_all_motors()

        mqtt_client.loop_forever()

if __name__ == "__main__":
    try:
        motor_control()
    except KeyboardInterrupt:
        print("[INFO] Stopping motors and cleaning up GPIO resources.")
        motor_control()

import RPi.GPIO as GPIO
from time import sleep
from gpiozero import Motor
from adafruit_motor import servo, motor
from paho.mqtt import client as mqtt_client
import sys

class MotorDriver:
    def __init__(self, driver, pin):
        if not isinstance(driver, (motor.DCMotor, servo.Servo)):
            raise TypeError("Invalid driver library instance")

        self.driver = driver
        self.pin = pin
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.pin, GPIO.OUT)
        self.pwm = GPIO.PWM(self.pin, 1000)
        self.pwm.start(0)

    def set_frequency(self, freq):
        try:
            self.pwm.ChangeFrequency(freq)
        except GPIO.exceptions.ValueError as e:
            raise MotorError(f"Failed to set PWM frequency: {e}")

    def set_duty_cycle(self, duty):
        if not 0 <= duty <= 255:
            raise MotorError("Duty cycle out of range (0-255)")

        try:
            self.pwm.ChangeDutyCycle(duty)
        except GPIO.exceptions.ValueError as e:
            raise MotorError(f"Failed to set PWM duty cycle: {e}")

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()
        GPIO.cleanup(self.pin)

    def close(self):
        self.stop()
        GPIO.cleanup(self.pin)

class MotorError(Exception):
    pass

def on_connect(client, userdata, flags, rc):
    print("Connected with result code "+str(rc))
    client.subscribe("motor/command")

def on_message(client, userdata, msg):
    command = msg.payload.decode()
    if command == "forward":
        motor.DCMotor(18).run_to_position(180, speed_sp=100, out_of_bounds=motor.OutOfBoundsBehavior.HOLD)
    elif command == "backward":
        motor.DCMotor(18).run_to_position(-180, speed_sp=100, out_of_bounds=motor.OutOfBoundsBehavior.HOLD)
    elif command == "stop":
        motor.DCMotor(18).stop()

client = mqtt_client.Client()
client.on_connect = on_connect
client.on_message = on_message

try:
    client.connect("mqtt.broker.url", 1883, 60)
    motor_driver = MotorDriver(motor.DCMotor(18), 18)
    client.loop_forever()
except KeyboardInterrupt:
    motor_driver.close()
    client.disconnect()
    sys.exit(0)

