import time
import RPi.GPIO as GPIO
import adafruit_motor.servo.sg90 as SG90
import paho.mqtt.client as mqtt

class RoboticArm:
    def __init__(self):
        self.base = SG90.Servo(17)
        self.shoulder = SG90.Servo(27)
        self.gripper = SG90.Servo(22)

    def move_joint(self, joint, target_angle):
        try:
            if not (-90 <= target_angle <= 90):
                raise driver_library.exc.OutputDeviceBadValue(f"Invalid angle {target_angle} for joint {joint}")
            joint.angle = target_angle
            time.sleep(0.4)
        except ValueError as e:
            print(f"Pin conflict error: {e}")
        except driver_library.exc.OutputDeviceBadValue as e:
            print(f"Invalid angle error: {e}")

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        print(f"Moving to pose: base={base_angle}, shoulder={shoulder_angle}, gripper={gripper_angle}")
        self.move_joint(self.base, base_angle)
        self.move_joint(self.shoulder, shoulder_angle)
        self.move_joint(self.gripper, gripper_angle)

    def run_demo_sequence(self):
        poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20), (0, 0, 0)]
        for pose in poses:
            self.go_to_pose(*pose)
            time.sleep(2)

def on_connect(client, userdata, flags, rc):
    print("Connected to MQTT broker")
    client.subscribe("#")

def on_message(client, userdata, msg):
    print(f"Received message: {msg.topic}: {msg.payload.decode()}")

def main():
    GPIO.setmode(GPIO.BCM)

    try:
        arm = RoboticArm()
        mqtt_client = mqtt.Client()
        mqtt_client.on_connect = on_connect
        mqtt_client.on_message = on_message
        mqtt_client.connect("mqtt.example.com", port=1883)
        mqtt_client.loop_forever()

        try:
            arm.run_demo_sequence()
        except (RuntimeError, driver_library.exc.OutputDeviceBadValue, ValueError) as e:
            print(f"Error during demo sequence: {e}")

    finally:
        arm.base.release()
        arm.shoulder.release()
        arm.gripper.release()
        GPIO.cleanup()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

