from crcmod.predefined import CRC_16_MODBUS
from gpiozero import DeviceNotFoundError

class ModbusRTUServoMotor:
    def __init__(self, port="/dev/serial0", baudrate=115200, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None
        self.crc = CRC_16_MODBUS()
        self.register_map = {
            1000: {'R/W': 'R', 'Register': 0x0000, 'functioncode': 3},
            1001: {'R/W': 'R', 'Register': 0x0001, 'functioncode': 3},
            1002: {'R/W': 'W', 'Register': 0x0000, 'functioncode': 6},
            # Add more registers as needed
        }

    def __enter__(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            return self
        except (serial.SerialException, DeviceNotFoundError):
            logging.warning(f"Unable to open serial port {self.port} or device not found.")
            return None

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial:
            self.serial.close()

    def read_registers(self, reg_addr):
        if reg_addr not in self.register_map:
            raise ValueError(f"Invalid register address: {reg_addr}")
        if self.register_map[reg_addr]['R/W'] != 'R':
            raise ValueError(f"Register {reg_addr} is not readable.")

        data = b''
        try:
            self.serial.write(self._build_request(reg_addr))
            time.sleep(0.005)  # Wait for response
            data = self.serial.read(10)
            if len(data) < 10:
                raise serial.SerialException("Incomplete response received.")
        except serial.SerialException as e:
            logging.error(f"Error reading from serial port: {e}")
            return None

        crc = data[-2:]
