            self.automation_hat.initialize()
            return True
        except OSError as e:
            logging.error(f"Error initializing Automation HAT: {e}")
            return False

    def get_door_state(self):
        state = GPIO.input(self.state_pin)
        if state is None:
            logging.error("Invalid state value. Exiting...")
            exit(1)
        return state

    def door_action(self, action):
        if action not in ["open", "close"]:
            logging.error(f"Invalid action: {action}. Exiting...")
            exit(1)

        if action == "open":
            GPIO.output(self.relay, GPIO.HIGH)
            time.sleep(0.5)
            GPIO.output(self.relay, GPIO.LOW)
        elif action == "close":
            GPIO.output(self.relay, GPIO.HIGH)

