            logging.info("Connected to MQTT broker")
            client.publish("garage/state", self.door_state)
        else:
            logging.error(f"Failed to connect to MQTT broker: {rc}")

    def run(self):
        while True:
            door_state = self.get_door_state()
            if door_state != self.door_state:
                self.door_state = door_state
                self.door_action(self.door_state_action())
                self.mqtt_client.publish("garage/state", self.door_state)
            time.sleep(1)

    def door_state_action(self):
        if self.door_state:
            return "close"
        return "open"

    def shutdown(self):
        self.door_action("off")
        self.mqtt_client.disconnect()
        GPIO.cleanup()

