i2c = smbus.SMBus(1)

def check_i2c_device(address):
    try:
        i2c.write_byte_data(address, adafruit_seesaw.Seesaw.ID, 0x00)
        return True
    except IOError:
        return False

def check_sensor_presence():
    for addr in range(0x40, 0x43):
        if check_i2c_device(addr):
            return addr
    return None

def read_moisture():
    try:
        sensor = adafruit_seesaw.Seesaw(i2c, address=I2C_ADDR)
        return sensor.moisture
    except RuntimeError as e:
        print(f"Error reading moisture: {e}")
        return None

def turn_on_pump(status):
    if status:
        GPIO.output(17, GPIO.HIGH)
    else:
        GPIO.output(17, GPIO.LOW)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker!")
        client.publish(MQTT_TOPIC, "Initializing...")

def on_message(client, userdata, msg):
    print(f"{msg.topic}: {msg.payload.decode()}")

def main():
    sensor_address = check_sensor_presence()
    if not sensor_address:
        print("No Seesaw sensor found on I2C bus.")
        return

    I2C_ADDR = sensor_address

    client = mqtt_client.Client()
    client.on_connect = on_connect
    client.on_message = on_message

    client.connect(MQTT_BROKER, MQTT_PORT, 60)

    try:
        while True:
            moisture = read_moisture()
            if moisture is not None:
                if moisture < 500:
                    turn_on_pump(True)
                    client.publish(MQTT_TOPIC, f"Moisture: {moisture}, Pump: ON")
                else:
                    turn_on_pump(False)
                    client.publish(MQTT_TOPIC, f"Moisture: {moisture}, Pump: OFF")

            time.sleep(10)
    except KeyboardInterrupt:
        print("Exiting...")
        turn_on_pump(False)
        GPIO.cleanup()
        i2c.close()
        client.disconnect()

