        self.ser.write_bytes(f'AT+GPSRD={interval_seconds}\r\n'.encode())
        response = self.read_response()
        if response is None:
            return
        if 'OK' not in response:
            self.log.warning(f"Failed to set GPS reporting: {response}")

    def set_message_storage(self, storage='SM'):
        self.ser.write_bytes(f'AT+CPMS="{storage}", "SM", "SM"\r\n'.encode())
        response = self.read_response()
        if response is None:
            return
        if 'OK' not in response:
            self.log.warning(f"Failed to set message storage: {response}")

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        self.ser.write_bytes(b'AT+CIPSTART="TCP", "{}", {}'.format(ip, port).encode())
        response = self.read_response()
        if response is None:
            return
        if 'ERROR' in response:
            self.log.warning(f"Failed to open TCP connection: {response}")
            return

        self.ser.write_bytes(b'\x1A')
        self.ser.write(data)
        self.ser.write_bytes(b'\x1A')
        self.ser.write_bytes(b'AT+CIPCLOSE\r\n'.encode())
        response = self.read_response()
        if response is None:
            return
        if 'OK' not in response:
            self.log.warning(f"Failed to close TCP connection: {response}")

    def send_terminator(self):
        self.ser.write_bytes(b'\x1A')
        response = self.read_response()
        if response is None:
            return
        if 'OK' not in response:
            self.log.warning(f"Failed to send terminator: {response}")

atexit.register(GSMModule.__exit__)

if __name__ == "__main__":
    try:
        with GSMModule():
            # Use the GSMModule instance here
            pass
    except KeyboardInterrupt:
        pass

