import gpiozero
import RPi.GPIO as GPIO
from picamera2 import Camera
from adafruit_mqtt.client import MQTT_Client
from http.server import BaseHTTPRequestHandler, HTTPServer

class RelayController:
    def __init__(self):
        self.relay = gpiozero.OutputDevice(23, active_high=True)
        self.mqtt_client = MQTT_Client()

    def on_shutdown(self, signum, frame):
        self.relay.off()
        GPIO.cleanup()
        sys.exit(0)

    def handle_mqtt_connect(self, client, userdata, flags, rc):
        if rc == 0:
            print("Connected to MQTT broker")
            self.mqtt_client.subscribe("relay/set")

    def handle_mqtt_message(self, client, userdata, msg):
        data = json.loads(msg.payload)
        if "state" in data:
            state = data["state"].lower()
            if state == "on":
                self.relay.on()
            elif state == "off":
                self.relay.off()
            else:
                print("Invalid state value")

    def start_mqtt(self):
        mqtt_broker = "your_mqtt_broker"
        mqtt_port = 1883
        mqtt_client_id = "relay_controller"
        self.mqtt_client.on_connect = self.handle_mqtt_connect
        self.mqtt_client.on_message = self.handle_mqtt_message
        self.mqtt_client.connect(mqtt_broker, mqtt_port, 60)
        self.mqtt_client.loop_forever()

    def start_http_server(self):
        HTTPRequestHandler.protocol_version = "HTTP/1.1"

        class RelayHandler(BaseHTTPRequestHandler):
            def do_POST(self):
                if self.path == "/relay":
                    content_length = int(self.headers['Content-Length'])
                    post_data = self.rfile.read(content_length).decode('utf-8')
                    try:
                        data = json.loads(post_data)
                        if "state" in data:
                            state = data["state"].lower()
                            if state == "on" or state == "off":
                                if state == "on":
                                    self.relay.on()
                                else:
                                    self.relay.off()
                                self.send_response(200)
                                self.end_headers()
                                self.wfile.write(json.dumps({"status": "Relay state changed"}).encode('utf-8'))
                            else:
                                self.send_response(400)
                                self.end_headers()
                                self.wfile.write(json.dumps({"error": "Invalid request"}).encode('utf-8'))
                    except (ValueError, KeyError):
                        self.send_response(400)
                        self.end_headers()
                        self.wfile.write(json.dumps({"error": "Invalid request"}).encode('utf-8'))
                else:
                    self.send_response(404)
