class ServoKit:
    def __init__(self, i2c_bus=1, address=0x40):
        self.kit = adafruit_servokit.ServoKit(i2c_bus=i2c_bus)
        self.kit.address = address
        atexit.register(self.kit.exit)

    def validate_channel(self, channel):
        if not (0 <= channel < 16):
            raise ValueError("Channel must be between 0 and 15")

    def validate_angle(self, angle):
        if not (0 <= angle <= 180):
            raise ValueError("Angle must be between 0 and 180")

    def grab_object(self):
        self.move_servo(0, 90)

    def release_object(self):
        self.move_servo(0, 150)

    def move_servo(self, channel, angle):
        self.validate_channel(channel)
        self.validate_angle(angle)

        try:
            servo = self.kit.servo[channel]
            for current_angle in range(servo.value, angle, 5):
                servo.angle = current_angle
                time.sleep(0.04)
        except (OSError, ValueError) as e:
            print(f"Error moving servo: {e}")
        except KeyboardInterrupt:
            print("Interrupted, cleaning up...")
            self.kit.exit()
            sys.exit(1)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_disconnect(client, userdata, rc):
