                kit.move_servo(channel, angle)
            else:
                print("Invalid command")
    except KeyboardInterrupt:
        print("Interrupted, cleaning up...")
        mqtt_client.disconnect()
        kit.kit.exit()
        sys.exit(0)

if __name__ == "__main__":
    main()

