from gpiozero import LED, OutputDevice
from keywords import Keywords

class Actuator:
    def __init__(self, pin, name):
        try:
            self.device = gpiozero.OutputDevice(pin, initial_value=False)
            self.name = name
        except Exception as e:
            print(f"Error initializing {name}: {e}")
            self.device = None

    def on(self):
        if self.device:
            self.device.on()

    def off(self):
        if self.device:
            self.device.off()

    def close(self):
        if self.device:
            self.device.close()

class HydroponicsSystem:
    def __init__(self):
        self.pump = Actuator(20, "pump")
        self.light = Actuator(21, "light")
        self.keywords = Keywords()
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.connect("mqtt.broker.url", 1883, 60)

    def on_connect(self, client, userdata, flags, rc):
        print(f"Connected with result code {rc}")
        self.mqtt_client.subscribe("#")

    def parse_intent(self, phrase):
        intent = self.keywords.match(phrase.lower())
        if intent is None:
            print("Unknown command")
            return None
        return getattr(self, intent)

    def turn_pump_on(self):
        self.pump.on()
        print(f"Turned pump on")

    def turn_pump_off(self):
        self.pump.off()
        print(f"Turned pump off")

    def toggle_light(self):
        self.light.device.toggle()
        print(f"Toggled light")

    def run(self):
        while True:
            try:
                phrase = input("Enter a command: ")
                intent = self.parse_intent(phrase)
                if intent is not None:
                    getattr(self, intent)()
            except KeyboardInterrupt:
                print("Exiting...")
                self.pump.close()
                self.light.close()
                self.mqtt_client.disconnect()
                break

if __name__ == "__main__":
    system = HydroponicsSystem()
    system.run()

class Keywords:
