i2c = busio.I2C(board.SCL, board.SDA)

def check_sensor_presence(i2c):
    try:
        sensor = CCS811(i2c)
        return True
    except OSError as e:
        print(f"Error checking sensor presence: {e}")
        return False

def read_co2_level(sensor):
    try:
        eco2 = sensor.eco2
        return eco2
    except OSError as e:
        print(f"Error reading CO2 level: {e}")
        return None

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_publish(client, userdata, mid):
    print(f"Published message with mid: {mid}")

def main():
    if not check_sensor_presence(i2c):
        print("CCS811 sensor not found. Exiting...")
        sys.exit(1)

    sensor = CCS811(i2c)
    sensor.start_i2c()

    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_publish = on_publish
    mqtt_client.connect("mqtt.example.com", 1883, 60)

    try:
        while True:
            co2_level = read_co2_level(sensor)
            if co2_level is not None:
