import sys
import time
import datetime
import RTC
from gpiozero import I2C
from adafruit_bus_device.i2c_device import I2CDevice
from paho.mqtt import client as mqtt_client

# DS1338 RTC I2C address
DS1338_I2C_ADDR = 0x68

# I2C bus configuration
i2c = I2C(sda=2, scl=3)
rtc = RTC.DS1338(i2c, DS1338_I2C_ADDR)

def check_rtc():
    try:
        rtc.read_all()
        return True
    except OSError:
        print("DS1338 RTC not found.")
        return False

def bcd_to_int(value):
    return value & 0x0F * 10 + (value >> 4)

def int_to_bcd(value):
    return ((value // 10) << 4) + (value % 10)

def read_datetime(century=21):
    data = rtc.read_all()

    if not data:
        return None

    year = bcd_to_int(data[RTC.YEAR]) + century * 100
    month = bcd_to_int(data[RTC.MONTH])
    day = bcd_to_int(data[RTC.DAY])
    hour = (bcd_to_int(data[RTC.HOUR]) & 0x3F)
    minute = bcd_to_int(data[RTC.MINUTE])
    second = bcd_to_int(data[RTC.SECOND])

    return datetime.datetime(year, month, day, hour, minute, second)

def write_all(year=None, month=None, day=None, hour=None, minute=None, second=None):
    if year is None:
        year = rtc.read_year() + 21
    if month is None:
        month = rtc.read_month()
    if day is None:
        day = rtc.read_day()
    if hour is None:
        hour = rtc.read_hour()
    if minute is None:
        minute = rtc.read_minute()
    if second is None:
        second = rtc.read_second()

    year_bcd = int_to_bcd(year % 100)
    hour_bcd = int_to_bcd((hour & 0x3F) | (hour >= 12 and 0x40))

    rtc.write(RTC.SECOND, int_to_bcd(second))
    rtc.write(RTC.MINUTE, int_to_bcd(minute))
    rtc.write(RTC.HOUR, hour_bcd)
    rtc.write(RTC.DAY, int_to_bcd(day))
    rtc.write(RTC.MONTH, int_to_bcd(month))
    rtc.write(RTC.YEAR, year_bcd)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker.")
        client.subscribe("#")

def on_message(client, userdata, msg):
    print(f"Received message: {msg.topic}: {msg.payload.decode()}")

    command = msg.payload.decode().strip().split(" ")
    if len(command) == 7:
        write_all(int(command[0]), int(command[1]), int(command[2]), int(command[3]), int(command[4]), int(command[5]))

def main():
    if not check_rtc():
        sys.exit(1)

    mqtt_client = mqtt_client.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message

    mqtt_client.connect("mqtt.example.com", 1883, 60)
    mqtt_client.loop_forever()

    try:
        while True:
            time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        i2c.deinit()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

