        self.uart.rxd_handler = self.uart.read

        self.uart.is_open()

    def _send_command(self, command, delay=1, max_retries=3):
        self.uart.write((command + b'\r\n').encode())
        time.sleep(delay)
        response = self._read_response(max_retries)
        return response

    def _read_response(self, max_retries):
        start_time = time.time()
        response = b''
        while time.time() - start_time < 5:
            try:
                data = self.uart.read(self.uart.in_waiting)
                response += data
                if b'OK\r\n' in response or b'ERROR\r\n' in response or b'FAIL\r\n' in response:
                    break
            except serial.SerialException:
                if max_retries > 0:
                    time.sleep(1)
                    max_retries -= 1
                else:
                    raise Exception("No valid response received")
        if b'OK\r\n' in response:
            return response.decode().strip()
        elif b'ERROR\r\n' in response:
            raise Exception(response.decode().strip())
        elif b'FAIL\r\n' in response:
            raise Exception(response.decode().strip())
        else:
            raise Exception("No valid response received")

    def test_connection(self):
        return self._send_command('AT\r\n') == 'OK'

    def restart(self):
        self._send_command('AT+RST\r\n', max_retries=0)
        time.sleep(2)
        return self._send_command('AT\r\n') == 'OK'

    def connect_wifi(self, ssid, password):
        self._send_command('AT+CWMODE=1\r\n')
        self._send_command(f'AT+CWJAP_CUR="{ssid}", "{password}"\r\n', max_retries=0)
        time.sleep(5)
        return 'WIFI GOT IP' in self._read_response(max_retries=0)

    def on_terminate(self):
        self.uart.close()

    def __del__(self):
        self.on_terminate()

def on_connect(client, userdata, flags, rc):
    print("Connected with result code "+str(rc))

    client.subscribe("#")

def on_message(client, userdata, msg):
    print(msg.topic+" "+str(msg.payload))

def main():
    mqtt_client = MQTTClient("esp8266", "test.mosquitto.org", port=1883, ssl=True, ssl_context=ssl.create_default_context())
    mqtt_client.on_connect = on_connect
